        c = _c;
    }

    receive() external payable {}

    function run(bytes32 hash, uint value) public payable {
        require(value == 1 ether, "value must be 1 ether");
        require(address(this).balance >= value, "insufficient balance");

        c.lockInGuess{value: value}(hash);

        bool settleSucceeded;
        try c.settle() {
            settleSucceeded = true;
        } catch {
            settleSucceeded = false;
        }

        // Since guesses is not public, infer its effects from observable behavior:
        // - If settle succeeded, the block was cleared.
        // - If settle reverted, the block must have remained nonzero (since lockInGuess succeeded and set it).
        // We can observe the clearing by attempting another settle: it should revert if block is 0.
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }

        if (settleSucceeded) {
            // After a successful settle, block should be 0, so a second settle must revert.
            assert(secondSettleReverted);
        } else {
            // After a reverted settle in the same transaction/block, the block is still nonzero
            // and we cannot settle again in the same block, so second settle also reverts.
            assert(secondSettleReverted);
        }
    }
}

